sourcesContent:
import db from '../models/index.js';

const createBooking = async (data, userIdFromToken) => {
  try {
    // 1. Kiểm tra tour
    const tour = await db.Tour.findByPk(data.tourId);
    if (!tour) {
      return {
        errCode: 1,
        errMessage: 'Tour không tồn tại'
      };
    }

    // 2. Tạo booking (statusid = 1 → PENDING)
    const booking = await db.Booking.create({
      userId: userIdFromToken,
      tourId: data.tourId,
      bookingDate: data.bookingDate || new Date(),
      totalAdults: Number(data.totalAdults),
      totalChildren: Number(data.totalChildren),
      notes: data.notes || null,
      acceptTerms: data.acceptTerms === true,
      totalPrice: Number(data.totalPrice) || 0,
      statusid: 1
    });

    return {
      errCode: 0,
      errMessage: 'Đặt tour thành công (chưa thanh toán)',
      booking
    };

  } catch (err) {
    console.error('createBooking error:', err);
    return {
      errCode: -1,
      errMessage: 'Tạo booking thất bại'
    };
  }
};

export default {
  createBooking
};

